+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "imagefiltermodel.h"
+
+#include <QDir>
+#include <QUrl>
+
+#include "model/imageproxymodel.h"
+
+ImageFilterModel::ImageFilterModel(QObject *parent)
+    : QSortFilterProxyModel(parent)
+{
+    setSortCaseSensitivity(Qt::CaseInsensitive);
+    sort(0);
+
+    connect(this, &ImageFilterModel::rowsInserted, this, &ImageFilterModel::countChanged);
+    connect(this, &ImageFilterModel::rowsRemoved, this, &ImageFilterModel::countChanged);
+    connect(this, &ImageFilterModel::modelReset, this, &ImageFilterModel::countChanged);
+}
+
+void ImageFilterModel::setSourceModel(QAbstractItemModel *model)
+{
+    if (sourceModel()) {
+        disconnect(sourceModel(), &QAbstractItemModel::columnsInserted, this, nullptr);
+    }
+
+    QSortFilterProxyModel::setSourceModel(model);
+
+    if (model) {
+        // QConcatenateTablesProxyModel inserts the rows of its first model before it has columns,
+        // so those rows could not be filtered yet
+        connect(model, &QAbstractItemModel::columnsInserted, this, [this] {
+            beginFilterChange();
+            endFilterChange(Direction::Rows);
+        });
+    }
+}
+
+int ImageFilterModel::count() const
+{
+    return rowCount();
+}
+
+bool ImageFilterModel::showSystemWallpapers() const
+{
+    return m_showSystemWallpapers;
+}
+
+void ImageFilterModel::setShowSystemWallpapers(bool show)
+{
+    if (m_showSystemWallpapers == show) {
+        return;
+    }
+
+    beginFilterChange();
+    m_showSystemWallpapers = show;
+    endFilterChange(Direction::Rows);
+    Q_EMIT showSystemWallpapersChanged();
+}
+
+QString ImageFilterModel::currentImage() const
+{
+    return m_currentImage;
+}
+
+void ImageFilterModel::setCurrentImage(const QString &image)
+{
+    if (m_currentImage == image) {
+        return;
+    }
+
+    beginFilterChange();
+    m_currentImage = image;
+    m_currentImagePath = QDir::cleanPath(QUrl::fromUserInput(image).toLocalFile());
+    endFilterChange(Direction::Rows);
+    Q_EMIT currentImageChanged();
+}
+
+int ImageFilterModel::indexOf(const QString &path) const
+{
+    const auto model = qobject_cast<const ImageProxyModel *>(sourceModel());
+    if (!model) {
+        return -1;
+    }
+
+    const int sourceRow = model->indexOf(path);
+    if (sourceRow < 0) {
+        return -1;
+    }
+
+    return mapFromSource(model->index(sourceRow, 0)).row();
+}
+
+void ImageFilterModel::openContainingFolder(int row) const
+{
+    if (const auto model = qobject_cast<const ImageProxyModel *>(sourceModel())) {
+        model->openContainingFolder(mapToSource(index(row, 0)).row());
+    }
+}
+
+bool ImageFilterModel::filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const
+{
+    if (m_showSystemWallpapers) {
+        return true;
+    }
+
+    const QModelIndex index = sourceModel()->index(sourceRow, 0, sourceParent);
+    if (index.data(ImageRoles::RemovableRole).toBool()) {
+        return true;
+    }
+
+    return !m_currentImagePath.isEmpty() && QDir::cleanPath(index.data(ImageRoles::SourceRole).toUrl().toLocalFile()) == m_currentImagePath;
+}
diff --git a/wallpapers/image/plugin/imagefiltermodel.h b/wallpapers/image/plugin/imagefiltermodel.h
