+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#pragma once
+
+#include <QSortFilterProxyModel>
+#include <qqmlregistration.h>
+
+/**
+ * Sorts the wallpapers of ImageProxyModel by name and optionally hides
+ * the ones installed with the system.
+ */
+class ImageFilterModel : public QSortFilterProxyModel
+{
+    Q_OBJECT
+    QML_ELEMENT
+
+    Q_PROPERTY(int count READ count NOTIFY countChanged)
+    /**
+     * Whether wallpapers the user can't remove are listed
+     */
+    Q_PROPERTY(bool showSystemWallpapers READ showSystemWallpapers WRITE setShowSystemWallpapers NOTIFY showSystemWallpapersChanged)
+    /**
+     * The wallpaper in use, which is always listed
+     */
+    Q_PROPERTY(QString currentImage READ currentImage WRITE setCurrentImage NOTIFY currentImageChanged)
+
+public:
+    explicit ImageFilterModel(QObject *parent = nullptr);
+
+    void setSourceModel(QAbstractItemModel *model) override;
+
+    int count() const;
+
+    bool showSystemWallpapers() const;
+    void setShowSystemWallpapers(bool show);
+
+    QString currentImage() const;
+    void setCurrentImage(const QString &image);
+
+    Q_INVOKABLE int indexOf(const QString &path) const;
+    Q_INVOKABLE void openContainingFolder(int row) const;
+
+Q_SIGNALS:
+    void countChanged();
+    void showSystemWallpapersChanged();
+    void currentImageChanged();
+
+protected:
+    bool filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const override;
+
+private:
+    bool m_showSystemWallpapers = true;
+    QString m_currentImage;
+    QString m_currentImagePath;
+};
